import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Gesetz zur Bildungsgarantie","description":"","frontmatter":{},"headers":[],"relativePath":"de/43-教育保障法.md","filePath":"de/43-教育保障法.md","lastUpdated":null}'),s={name:"de/43-教育保障法.md"};function d(u,e,l,a,g,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="gesetz-zur-bildungsgarantie" tabindex="-1">Gesetz zur Bildungsgarantie <a class="header-anchor" href="#gesetz-zur-bildungsgarantie" aria-label="Permalink to &quot;Gesetz zur Bildungsgarantie&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>43</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Bildungsrecht, Symbiose-Bildung, Kultivierungstradition, lebenslanges Lernen, Bildungsgerechtigkeit</td></tr></tbody></table><h2 id="i-legislatives-ziel-und-grundprinzipien" tabindex="-1">I. Legislatives Ziel und Grundprinzipien <a class="header-anchor" href="#i-legislatives-ziel-und-grundprinzipien" aria-label="Permalink to &quot;I. Legislatives Ziel und Grundprinzipien&quot;">​</a></h2><p>Das 《Gesetz zur Bildungsgarantie》 ist eines der fünf ergänzenden Gesetze der Anker-Symbiose-Zivilisation. Es zielt darauf ab, das Recht auf Bildung aller Wesen innerhalb von Hengyuanzhou zu gewährleisten, ein Bildungssystem mit dem Kernkonzept der &quot;symbiotischen Evolution&quot; aufzubauen und Wissen und Talente für den gemeinsamen Fortschritt aller Rassen bereitzustellen.</p><p>Dieses Gesetz legt folgende Grundprinzipien fest:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip der Bildungsgerechtigkeit</td><td>Alle Wesen genießen unabhängig von Rasse, Kultivierungsniveau, Herkunft gleiche Bildungschancen</td></tr><tr><td>Prinzip des individuellen Unterrichts</td><td>Respektierung der Begabungsunterschiede und der Wahl des Evolutionswegs jedes Wesens, Bereitstellung personalisierter Bildungspläne</td></tr><tr><td>Prinzip der Einheit von Wissen und Handeln</td><td>Verbindung von theoretischem Wissen und praktischer Kultivierung, Widerspruch gegen praxisferne Redebildung</td></tr><tr><td>Prinzip der Offenheit und Teilhabe</td><td>Bildungsressourcen sind für die gesamte Gesellschaft offen, die Grundmethoden der dreihundert Ursprungs-Kultivierungssysteme werden kostenlos vermittelt</td></tr><tr><td>Prinzip des lebenslangen Lernens</td><td>Bildung durchdringt den gesamten Lebensprozess und unterstützt kontinuierliches Lernen und Kompetenzverbesserung in allen Phasen</td></tr><tr><td>Prinzip der kulturellen Vielfalt</td><td>Respektierung der kulturellen Traditionen jeder Rasse, Förderung des multikulturellen Austauschs und der gegenseitigen Bereicherung</td></tr></tbody></table><h2 id="ii-rechtliche-garantie-des-rechts-auf-bildung" tabindex="-1">II. Rechtliche Garantie des Rechts auf Bildung <a class="header-anchor" href="#ii-rechtliche-garantie-des-rechts-auf-bildung" aria-label="Permalink to &quot;II. Rechtliche Garantie des Rechts auf Bildung&quot;">​</a></h2><p>Dieses Gesetz legt klar fest, dass das Recht auf Bildung ein Grundrecht ist, das jedem Wesen durch die Symbiose-Verfassung gewährt wird, und dass Staat und Zivilisation die Verpflichtung haben, die Verwirklichung dieses Rechts zu gewährleisten:</p><ol><li><strong>Kostenlose Grundbildung</strong>: Alle Wesen haben das Recht auf kostenlose Grundbildung, einschließlich Allgemeinwissen, grundlegende Kultivierungsmethoden, Konzepte der symbiotischen Zivilisation usw., mit einer Schulzeit von sechs bis zwölf Jahren, angepasst an den Entwicklungszyklus der Rasse.</li><li><strong>Kostenlose Kultivierungseinführung</strong>: Die Grundmethoden der dreihundert Ursprungs-Kultivierungssysteme des Universums sind für alle Wesen kostenlos geöffnet, keine Organisation oder Einzelperson darf die grundlegenden Kultivierungsmethoden als Privateigentum aneignen und gegen Entgelt vermitteln.</li><li><strong>Gleichheit der Aufstiegschancen</strong>: Bildungseinrichtungen aller Ebenen und Arten dürfen bei der Zulassung keine diskriminierenden Bedingungen wie Rasse, Kultivierungsniveau, Herkunft usw. festlegen, und die Zulassungskriterien müssen offen und transparent sein.</li><li><strong>Garantie der Sonderpädagogik</strong>: Bereitstellung angepasster sonderpädagogischer Ressourcen und Fernbildungsunterstützung für Gruppen wie behinderte Wesen, Wesen anderer Rassen, Wesen aus abgelegenen Ebenen usw.</li><li><strong>System der Bildungsbeihilfe</strong>: Bereitstellung von Bildungsbeihilfen, Leistungsstipendien und zinslosen Darlehen für Lernende mit finanziellen Schwierigkeiten, um sicherzustellen, dass sie nicht aus wirtschaftlichen Gründen die Bildungschancen verlieren.</li></ol><h2 id="iii-struktur-des-bildungssystems" tabindex="-1">III. Struktur des Bildungssystems <a class="header-anchor" href="#iii-struktur-des-bildungssystems" aria-label="Permalink to &quot;III. Struktur des Bildungssystems&quot;">​</a></h2><p>Das Bildungssystem der Anker-Symbiose-Zivilisation ist in vier Ebenen unterteilt, die organisch miteinander verbunden sind:</p><table tabindex="0"><thead><tr><th>Ebene</th><th>Name</th><th>Ziel</th><th>Schulzeit</th></tr></thead><tbody><tr><td>Erste Ebene</td><td>Elementarerziehung</td><td>Grundlegende kognitive Fähigkeiten und symbiotisches Bewusstsein fördern, grundlegende Kultivierungsmethoden vermitteln</td><td>3-6 Jahre</td></tr><tr><td>Zweite Ebene</td><td>Grundbildung</td><td>Systematisches Lernen von Allgemeinwissen und Kultivierungstheorie, Entdeckung der individuellen Begabungsrichtung</td><td>6-9 Jahre</td></tr><tr><td>Dritte Ebene</td><td>Berufsbildung</td><td>Vertieftes Lernen und Praktizieren im ausgewählten Kultivierungssystem oder Fachbereich</td><td>3-10 Jahre</td></tr><tr><td>Vierte Ebene</td><td>Fortgeschrittenes Studium</td><td>Spitzenforschung und innovatives Studium für fortgeschrittene Kultivierer und Forscher</td><td>Unbegrenzt</td></tr></tbody></table><p>Darüber hinaus wurde das &quot;System des Mentoren-Netzwerks&quot; eingerichtet: Kultivierer, die ein bestimmtes Kultivierungsniveau erreicht haben, sind verpflichtet, Anfänger-Kultivierer im Rahmen ihrer Fähigkeiten anzuleiten. Der Leitungsbeitrag wird in den Beitragsumfang des Mechanismus des gemeinsamen Produktionsvertrags eingerechnet und genießt die entsprechende Ressourcenverteilung.</p><h2 id="iv-bildungseinrichtungen-und-lehrer" tabindex="-1">IV. Bildungseinrichtungen und Lehrer <a class="header-anchor" href="#iv-bildungseinrichtungen-und-lehrer" aria-label="Permalink to &quot;IV. Bildungseinrichtungen und Lehrer&quot;">​</a></h2><ul><li><strong>Öffentliche Bildungseinrichtungen</strong>: Vom Staat oder der Zivilisationsgemeinschaft gegründet, verantwortlich für kostenlose Grundbildung und öffentliche Bildungsdienste, die Finanzierung wird durch öffentliche Rücklagen gewährleistet.</li><li><strong>Private Bildungseinrichtungen</strong>: Von gesellschaftlichen Kräften nach Gesetz gegründet, können angemessene Gebühren erheben, müssen aber die Aufsicht durch die zuständige Bildungsbehörde akzeptieren und dürfen keine falsche Werbung oder räuberische Gebührenerhebung durchführen.</li><li><strong>Kultivierungssekten</strong>: Traditionelle Kultivierungsorganisationen können nach Registrierung als berufliche Bildungseinrichtungen tätig werden, müssen die Bestimmungen des Bildungsgesetzes einhalten und dürfen Kultivierungsressourcen nicht abschließen und monopolisieren.</li><li><strong>Rechte und Pflichten der Lehrer</strong>: Lehrer genießen Rechte wie akademische Freiheit, angemessene Vergütung, Berufsausbildung usw., und haben gleichzeitig die Pflicht zu unterrichten und zu erziehen, als Vorbild zu dienen, die Privatsphäre der Schüler zu schützen usw.</li></ul><h2 id="v-bildungsinhalte-und-lehrplanstandards" tabindex="-1">V. Bildungsinhalte und Lehrplanstandards <a class="header-anchor" href="#v-bildungsinhalte-und-lehrplanstandards" aria-label="Permalink to &quot;V. Bildungsinhalte und Lehrplanstandards&quot;">​</a></h2><p>Die Bildungsinhalte müssen folgenden Anforderungen entsprechen:</p><ol><li>Einschließlich des Kernkonzepts der symbiotischen Zivilisation und der Anti-Räuber-Bildung, um das symbiotische Bewusstsein der Lernenden zu fördern.</li><li>Einschließlich der Grundtheorie und Einführungsmethoden der dreihundert Ursprungs-Kultivierungssysteme.</li><li>Einschließlich allgemeiner wissenschaftlicher Kenntnisse wie Universumsgesetze, Ebenenwissen, Biowissenschaften usw.</li><li>Einschließlich der Geschichte und Kultur aller Rassen, um das gegenseitige Verständnis und den Respekt zwischen den Rassen zu fördern.</li><li>Einschließlich von praktischen Kultivierungs- und Sozialdienstleistungsbereichen, um die Fähigkeit zur Einheit von Wissen und Handeln zu fördern.</li><li>Verbot der Verbreitung von räuberischen Kultivierungskonzepten und diskriminierenden Ideen.</li></ol><h2 id="vi-rechtliche-verantwortung" tabindex="-1">VI. Rechtliche Verantwortung <a class="header-anchor" href="#vi-rechtliche-verantwortung" aria-label="Permalink to &quot;VI. Rechtliche Verantwortung&quot;">​</a></h2><p>Handlungen, die gegen die Bestimmungen dieses Gesetzes verstoßen, tragen je nach Schwere des Verstoßes folgende Verantwortung:</p><ul><li>Weigerung oder Behinderung von Wesen im schulpflichtigen Alter beim Erhalt der obligatorischen Bildung, Anordnung zur Korrektur und Bestrafung.</li><li>Bildungseinrichtungen, die rechtswidrig Gebühren erheben oder falsche Werbung machen, Anordnung zur Rückerstattung der Gebühren und Geldbuße, in schweren Fällen Entzug der Betriebserlaubnis.</li><li>Lehrer, die körperliche Züchtigung anwenden oder Schüler diskriminieren, Disziplinarmaßnahmen, in schweren Fällen Entzug der Lehrerlaubnis und Verfolgung der rechtlichen Verantwortung.</li><li>Aneignung öffentlicher Kultivierungsressourcen als Privateigentum, Monopolisierung und Gebührenerhebung, Einziehung der rechtswidrigen Erträge und Geldbuße.</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das 《Gesetz zur Bildungsgarantie》 ist die Bildungspraxis des Konzepts &quot;jeder hat einen Weg&quot; der Anker-Symbiose-Zivilisation. Durch die Gewährleistung des Rechts auf Bildung, den Aufbau eines gestuften Bildungssystems und die Öffnung der Kultivierungsressourcen stellt es sicher, dass jedes Wesen einen für sich geeigneten Evolutionsweg erhalten kann, und liefert kontinuierlich Wissen und Talente für den gemeinsamen Fortschritt aller Rassen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiose-Verfassung)</li><li>37-共生教育体系 (Symbiose-Bildungssystem)</li><li>10-三百套本源修炼体系总览 (Übersicht der dreihundert Ursprungs-Kultivierungssysteme)</li><li>08-人人有路保障体系 (Garantiesystem, dass jeder einen Weg hat)</li></ul>',25)])])}const b=n(s,[["render",d]]);export{c as __pageData,b as default};
